import {initPhotoFit} from './photo-ui.js';
import {defaults,definitions,sanitize,toOBJ} from './model.js';
const $=s=>document.querySelector(s),canvas=$('#canvas'),gl=canvas.getContext('webgl',{antialias:true,alpha:true});
if(!gl){$('#status').textContent='WebGLを利用できません。Safariで開き直してください。';throw Error('WebGL unavailable');}
const shader=(type,source)=>{const s=gl.createShader(type);gl.shaderSource(s,source);gl.compileShader(s);if(!gl.getShaderParameter(s,gl.COMPILE_STATUS))throw Error(gl.getShaderInfoLog(s));return s;};
const program=gl.createProgram();gl.attachShader(program,shader(gl.VERTEX_SHADER,`attribute vec3 position,normal,color;uniform float yaw,pitch,zoom,aspect,target;varying vec3 N,C;void main(){mat3 ry=mat3(cos(yaw),0.,-sin(yaw),0.,1.,0.,sin(yaw),0.,cos(yaw));mat3 rx=mat3(1.,0.,0.,0.,cos(pitch),sin(pitch),0.,-sin(pitch),cos(pitch));vec3 p=rx*ry*(position-vec3(0.,target,0.));N=rx*ry*normal;C=color;gl_Position=vec4(p.x*zoom/aspect,p.y*zoom,p.z*-.25,1.);}`));gl.attachShader(program,shader(gl.FRAGMENT_SHADER,`precision mediump float;varying vec3 N,C;void main(){vec3 n=normalize(N);float key=max(0.,dot(n,normalize(vec3(-.5,.8,1.))));float rim=pow(1.-abs(n.z),3.);float spec=pow(max(0.,dot(n,normalize(vec3(-.2,.5,1.)))),30.);vec3 c=C*(.28+key*.75)+vec3(.08,.12,.16)*max(0.,-n.x)+rim*.10+spec*.13;gl_FragColor=vec4(c,1.);}`));gl.linkProgram(program);if(!gl.getProgramParameter(program,gl.LINK_STATUS))throw Error(gl.getProgramInfoLog(program));gl.useProgram(program);gl.enable(gl.DEPTH_TEST);
const bufs={};for(const name of ['position','normal','color']){bufs[name]=gl.createBuffer();const a=gl.getAttribLocation(program,name);gl.bindBuffer(gl.ARRAY_BUFFER,bufs[name]);gl.enableVertexAttribArray(a);gl.vertexAttribPointer(a,3,gl.FLOAT,false,0,0);}
const uniforms={};for(const k of ['yaw','pitch','zoom','aspect','target'])uniforms[k]=gl.getUniformLocation(program,k);
let params={...defaults},mode='body',mesh=null,yaw=.25,pitch=0,zoom=1.04,wire=false,seq=0,worker=null,timer,working=false;
try{params=sanitize(JSON.parse(localStorage.getItem('form-settings')||'{}'));}catch{}
const controls=$('#controls');for(const [title,ds] of definitions){const h=document.createElement('h2');h.textContent=title;controls.append(h);for(const [k,name,min,max,step] of ds){const l=document.createElement('label');l.className='param';l.innerHTML=`<span>${name}<output id="o-${k}"></output></span><input aria-label="${name}" id="p-${k}" type="range" min="${min}" max="${max}" step="${step}">`;controls.append(l);l.querySelector('input').addEventListener('input',e=>{params[k]=Number(e.target.value);sync();clearTimeout(timer);timer=setTimeout(rebuild,220);});}}
function sync(){for(const k in defaults){$('#p-'+k).value=params[k];$('#o-'+k).textContent=k==='height'?Math.round(params[k]*100)+' cm':params[k].toFixed(2);}try{localStorage.setItem('form-settings',JSON.stringify(params));}catch{}}
function draw(){const dpr=Math.min(devicePixelRatio,2),w=Math.round(canvas.clientWidth*dpr),h=Math.round(canvas.clientHeight*dpr);if(canvas.width!==w||canvas.height!==h){canvas.width=w;canvas.height=h;}gl.viewport(0,0,w,h);gl.clearColor(0,0,0,0);gl.clear(gl.COLOR_BUFFER_BIT|gl.DEPTH_BUFFER_BIT);if(!mesh)return;gl.uniform1f(uniforms.yaw,yaw);gl.uniform1f(uniforms.pitch,pitch);gl.uniform1f(uniforms.zoom,zoom);gl.uniform1f(uniforms.aspect,w/h);gl.uniform1f(uniforms.target,mode==='face'?mesh.headY:mesh.height*.51);gl.drawArrays(wire?gl.LINES:gl.TRIANGLES,0,mesh.vertices.length/3*(wire?2:1));}
new ResizeObserver(draw).observe(canvas);
function uploadGeometry(){for(const [a,b] of [['position','vertices'],['normal','normals'],['color','colors']]){let data=mesh[b];if(wire){const expanded=new Float32Array(data.length*2);let j=0;for(let i=0;i<data.length;i+=9)for(const k of [0,3,3,6,6,0])for(let c=0;c<3;c++)expanded[j++]=data[i+k+c];data=expanded;}gl.bindBuffer(gl.ARRAY_BUFFER,bufs[a]);gl.bufferData(gl.ARRAY_BUFFER,data,gl.STATIC_DRAW);}}
function rebuild(){working=true;$('#export').disabled=true;$('#status').textContent='数式からメッシュを生成中…';worker?.terminate();worker=new Worker(new URL('./worker.js',import.meta.url),{type:'module'});const id=++seq;worker.onmessage=({data})=>{if(data.id!==seq)return;if(data.error){$('#status').textContent='生成エラー: '+data.error;working=false;return;}mesh=data.mesh;uploadGeometry();$('#status').textContent=(mesh.vertices.length/9).toLocaleString()+' triangles · '+(mode==='face'?'顔モデル':'全身モデル');$('#export').disabled=false;working=false;draw();};worker.onerror=()=>{$('#status').textContent='生成処理に失敗しました。密度を下げて再試行してください。';working=false;};worker.postMessage({params,res:Number($('#quality').value),face:mode==='face',source:$('#source').value,id});}
function download(text,name,type){const u=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),60000);}
$('#export').onclick=()=>{if(mesh&&!working)download(toOBJ(mesh),'form-'+mode+'.obj','text/plain');};$('#save').onclick=()=>download(JSON.stringify({version:1,params},null,2),'form-settings.json','application/json');
$('#load').onchange=async e=>{try{const d=JSON.parse(await e.target.files[0].text());if(d.version!==1||!d.params)throw Error('対応していない設定形式です');params=sanitize(d.params);sync();rebuild();}catch(err){alert('読込できません: '+err.message);}e.target.value='';};
$('#reset').onclick=()=>{params={...defaults};sync();rebuild();};
for(const b of document.querySelectorAll('[data-preset]'))b.onclick=()=>{params={...defaults,...({slender:{shoulders:.9,waist:.84,hips:.96,muscle:.12,legs:1.06},athletic:{shoulders:1.13,waist:.92,muscle:.88}}[b.dataset.preset]||{})};sync();rebuild();};
for(const b of document.querySelectorAll('[data-view]'))b.onclick=()=>{mode=b.dataset.view;zoom=mode==='face'?5.3:1.04;yaw=.15;pitch=0;document.querySelectorAll('[data-view]').forEach(x=>x.classList.toggle('active',x===b));rebuild();};
$('#front').onclick=()=>{yaw=0;pitch=0;draw();};$('#side').onclick=()=>{yaw=Math.PI/2;pitch=0;draw();};$('#back').onclick=()=>{yaw=Math.PI;pitch=0;draw();};$('#wire').onclick=()=>{wire=!wire;if(mesh)uploadGeometry();$('#wire').classList.toggle('active',wire);draw();};$('#quality').onchange=rebuild;$('#source').onchange=rebuild;
const pointers=new Map();let pinch=0;
canvas.onpointerdown=e=>{canvas.setPointerCapture(e.pointerId);pointers.set(e.pointerId,[e.clientX,e.clientY]);pinch=0;};canvas.onpointermove=e=>{const old=pointers.get(e.pointerId);if(!old)return;pointers.set(e.pointerId,[e.clientX,e.clientY]);if(pointers.size===1){yaw+=(e.clientX-old[0])*.008;pitch=Math.max(-1.2,Math.min(1.2,pitch+(e.clientY-old[1])*.006));}else{const [a,b]=[...pointers.values()],d=Math.hypot(a[0]-b[0],a[1]-b[1]);if(pinch)zoom=Math.max(.5,Math.min(15,zoom*d/pinch));pinch=d;}draw();};for(const ev of ['pointerup','pointercancel','lostpointercapture'])canvas.addEventListener(ev,e=>{pointers.delete(e.pointerId);pinch=0;});window.addEventListener('blur',()=>pointers.clear());canvas.addEventListener('wheel',e=>{e.preventDefault();zoom=Math.max(.5,Math.min(15,zoom*Math.exp(-e.deltaY*.001)));draw();},{passive:false});
$('#analyze').onchange=async e=>{try{const f=e.target.files[0];if(f.size>25e6)throw Error('25MB以下のOBJを選んでください');const rows=(await f.text()).split(/\r?\n/).filter(l=>/^v\s/.test(l)).map(l=>l.trim().split(/\s+/).slice(1,4).map(Number)).filter(v=>v.length===3&&v.every(Number.isFinite));if(rows.length<10)throw Error('頂点が不足しています');let min=Infinity,max=-Infinity;for(const v of rows){min=Math.min(min,v[1]);max=Math.max(max,v[1]);}const h=max-min;if(h<=0)throw Error('Y方向の高さがありません');const report={vertices:rows.length,height:h,sections:[]};for(let i=1;i<20;i++){const y=min+i*h/20,sl=rows.filter(v=>Math.abs(v[1]-y)<h/40);if(sl.length){let xl=Infinity,xh=-Infinity,zl=Infinity,zh=-Infinity;for(const v of sl){xl=Math.min(xl,v[0]);xh=Math.max(xh,v[0]);zl=Math.min(zl,v[2]);zh=Math.max(zh,v[2]);}report.sections.push({heightFraction:i/20,width:(xh-xl)/h,depth:(zh-zl)/h,samples:sl.length});}}$('#analysis').textContent=JSON.stringify(report,null,2);download(JSON.stringify(report,null,2),'mesh-analysis.json','application/json');}catch(err){$('#analysis').textContent=err.message;}};
canvas.addEventListener('webglcontextlost',e=>{e.preventDefault();$('#status').textContent='3D表示が中断されました。ページを再読み込みしてください。';});sync();rebuild();window.formDebug={get mesh(){return mesh},get working(){return working},get params(){return params}};

initPhotoFit({getState:()=>({params:{...params},source:$('#source').value,mode}),applyState:state=>{clearTimeout(timer);params=sanitize(state.params);$('#source').value=state.source;mode=state.mode;zoom=mode==='face'?5.3:1.04;yaw=0;pitch=0;document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===mode));sync();rebuild();}});
